// slide-01.js - Cover Page
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'cover',
  index: 1,
  title: 'SkillClaw: Collective Skill Evolution for Multi-User LLM Agent Ecosystems'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Decorative accent bar at top
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08,
    fill: { color: theme.accent }
  });

  // Main title
  slide.addText("SkillClaw", {
    x: 0.5, y: 1.6, w: 9, h: 1.2,
    fontSize: 72, fontFace: "Arial",
    color: theme.bg, bold: true, align: "center"
  });

  // Subtitle tagline
  slide.addText("Collective Skill Evolution for Multi-User LLM Agent Ecosystems", {
    x: 0.5, y: 2.8, w: 9, h: 0.6,
    fontSize: 24, fontFace: "Arial",
    color: theme.light, align: "center"
  });

  // Source reference
  slide.addText("arxiv.org/abs/2604.08377", {
    x: 0.5, y: 3.8, w: 9, h: 0.4,
    fontSize: 14, fontFace: "Arial",
    color: theme.accent, align: "center"
  });

  // Decorative bottom bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.545, w: 10, h: 0.08,
    fill: { color: theme.accent }
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "000814",
    secondary: "001d3d",
    accent: "003566",
    light: "ffc300",
    bg: "ffd60a"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-01-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

