// slide-02.js - Problem: Static Skills
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 2,
  title: 'Agent Skills Remain Static After Deployment'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText(slideConfig.title, {
    x: 0.5, y: 0.4, w: 9, h: 0.7,
    fontSize: 36, fontFace: "Arial",
    color: theme.primary, bold: true, align: "left"
  });

  // Subtitle
  slide.addText("Users Rediscover Solutions Independently", {
    x: 0.5, y: 1.0, w: 9, h: 0.4,
    fontSize: 18, fontFace: "Arial",
    color: theme.secondary, align: "left"
  });

  // Left card - Current Problem
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.6, w: 4.3, h: 2.8,
    fill: { color: theme.primary }
  });
  slide.addText("Current Reality", {
    x: 0.7, y: 1.75, w: 3.9, h: 0.4,
    fontSize: 16, fontFace: "Arial",
    color: theme.accent, bold: true, align: "left"
  });
  slide.addText([
    { text: "Skills manually installed from centralized hub", options: { bullet: true, breakLine: true } },
    { text: "Solutions from interactions don't persist", options: { bullet: true, breakLine: true } },
    { text: "Same failures observed repeatedly across users", options: { bullet: true, breakLine: true } },
    { text: "No system-level knowledge accumulation", options: { bullet: true } }
  ], {
    x: 0.7, y: 2.2, w: 3.9, h: 2.0,
    fontSize: 13, fontFace: "Arial",
    color: theme.bg, align: "left", valign: "top"
  });

  // Right card - The Gap
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.2, y: 1.6, w: 4.3, h: 2.8,
    fill: { color: theme.secondary }
  });
