// slide-03.js - Architecture Overview with 4-stage closed loop
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 3,
  title: 'Closed-Loop Pipeline: From Multi-User Interaction to Shared Skill Evolution'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText(slideConfig.title, {
    x: 0.5, y: 0.35, w: 9, h: 0.6,
    fontSize: 32, fontFace: "Arial",
    color: theme.primary, bold: true, align: "left"
  });

  // Architecture diagram - horizontal flow with 4 stages
  const boxW = 2.0;
  const boxH = 1.4;
  const startX = 0.5;
  const arrowY = 2.4;
  const stages = [
    { label: "Multi-User\nInteraction", color: theme.primary },
    { label: "Session\nCollection", color: theme.secondary },
    { label: "Agentic\nEvolver", color: theme.accent },
    { label: "Skill\nSync", color: theme.light }
  ];

  stages.forEach((stage, i) => {
    const x = startX + i * 2.4;

    // Stage box
    slide.addShape(pres.shapes.RECTANGLE, {
      x: x, y: arrowY, w: boxW, h: boxH,
      fill: { color: stage.color }
    });
    slide.addText(stage.label, {
      x: x, y: arrowY, w: boxW, h: boxH,
      fontSize: 14, fontFace: "Arial",
      color: stage.color === theme.light ? theme.primary : theme.bg,
      bold: true, align: "center", valign: "middle"
    });

    // Arrow between boxes
    if (i < stages.length - 1) {
      slide.addShape(pres.shapes.LINE, {
        x: x + boxW + 0.05, y: arrowY + boxH / 2,
        w: 0.35, h: 0,
        line: { color: theme.primary, width: 2 }
      });
      // Arrow head
      slide.addText(">", {
        x: x + boxW + 0.25, y: arrowY + boxH / 2 - 0.15,
        w: 0.2, h: 0.3,
        fontSize: 16, fontFace: "Arial",
        color: theme.primary, bold: true, align: "center", valign: "middle"
      });
    }
  });

  // Four stages label below boxes
  const labelY = arrowY + boxH + 0.15;
  slide.addText("Evidence", {
    x: startX, y: labelY, w: boxW, h: 0.3,
    fontSize: 11, fontFace: "Arial",
    color: theme.secondary, align: "center"
  });
  slide.addText("Attribution", {
    x: startX + 2.4, y: labelY, w: boxW, h: 0.3,
    fontSize: 11, fontFace: "Arial",
    color: theme.secondary, align: "center"
  });
  slide.addText("Evolution", {
    x: startX + 4.8, y: labelY, w: boxW, h: 0.3,
    fontSize: 11, fontFace: "Arial",
    color: theme.secondary, align: "center"
  });
  slide.addText("Distribution", {
    x: startX + 7.2, y: labelY, w: boxW, h: 0.3,
    fontSize: 11, fontFace: "Arial",
    color: theme.secondary, align: "center"
  });

  // Key description box at bottom
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.2, w: 9, h: 1.1,
    fill: { color: theme.primary }
  });
  slide.addText("The agentic evolver performs open-ended reasoning over interaction evidence—not predefined update rules—to propose skill mutations verified before merging into the shared repository.", {
    x: 0.7, y: 4.3, w: 8.6, h: 0.9,
    fontSize: 12, fontFace: "Arial",
    color: theme.bg, align: "left", valign: "middle"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("3", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "000814",
    secondary: "001d3d",
    accent: "003566",
    light: "ffc300",
    bg: "ffd60a"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-03-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

