// slide-05.js - Multi-User Trajectory Aggregation
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 5,
  title: 'Cross-User Trajectory Aggregation Exposes Skill Behavioral Boundaries'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText(slideConfig.title, {
    x: 0.5, y: 0.35, w: 9, h: 0.6,
    fontSize: 30, fontFace: "Arial",
    color: theme.primary, bold: true, align: "left"
  });

  // Left side - explanation
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.1, w: 4.5, h: 3.5,
    fill: { color: theme.secondary }
  });
  slide.addText("Why Cross-User Aggregation?", {
    x: 0.7, y: 1.25, w: 4.1, h: 0.4,
    fontSize: 16, fontFace: "Arial",
    color: theme.light, bold: true, align: "left"
  });
  slide.addText([
    { text: "Different users exercising the same skill under diverse contexts produce complementary views", options: { bullet: true, breakLine: true } },
    { text: "Reveals conditions under which a skill works AND when it breaks", options: { bullet: true, breakLine: true } },
    { text: "Single user rarely generates enough signal to separate generalizable improvement from idiosyncratic fix", options: { bullet: true } }
  ], {
    x: 0.7, y: 1.75, w: 4.1, h: 2.6,
    fontSize: 12, fontFace: "Arial",
    color: theme.bg, align: "left", valign: "top"
  });

  // Right side - compatible systems grid
  slide.addText("Compatible Claw-Style Systems", {
    x: 5.2, y: 1.1, w: 4.3, h: 0.4,
    fontSize: 14, fontFace: "Arial",
    color: theme.primary, bold: true, align: "left"
  });

  const systems = [
    "OpenClaw", "CoPaw", "IronClaw", "PicoClaw",
    "ZeroClaw", "NanoClaw", "NemoClaw"
  ];

  systems.forEach((sys, i) => {
    const row = Math.floor(i / 3);
    const col = i % 3;
    const x = 5.2 + col * 1.45;
    const y = 1.6 + row * 0.65;

    slide.addShape(pres.shapes.RECTANGLE, {
      x: x, y: y, w: 1.35, h: 0.5,
      fill: { color: theme.accent }
    });
    slide.addText(sys, {
      x: x, y: y, w: 1.35, h: 0.5,
      fontSize: 11, fontFace: "Arial",
      color: "FFFFFF", bold: true,
      align: "center", valign: "middle"
    });
  });

  // Key insight box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.2, y: 3.5, w: 4.3, h: 1.1,
    fill: { color: theme.primary }
  });
  slide.addText("Aggregated evidence from diverse user interactions enables the evolver to distinguish generalizable improvements from one-off fixes.", {
    x: 5.4, y: 3.55, w: 3.9, h: 1.0,
    fontSize: 12, fontFace: "Arial",
    color: theme.bg, align: "left", valign: "middle"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("5", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "000814",
    secondary: "001d3d",
    accent: "003566",
    light: "ffc300",
    bg: "ffd60a"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-05-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

