// slide-06.js - Case Study: Multimodal Creative Pipeline
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 6,
  title: 'Case Study: Multimodal Creative Pipeline — 6 Days of Evolution'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText(slideConfig.title, {
    x: 0.5, y: 0.35, w: 9, h: 0.5,
    fontSize: 28, fontFace: "Arial",
    color: theme.primary, bold: true, align: "left"
  });

  // Table header
  const tableData = [
    [
      { text: "Day", options: { fill: { color: theme.primary }, color: "FFFFFF", bold: true, align: "center" } },
