      { text: "Outcome", options: { fill: { color: theme.primary }, color: "FFFFFF", bold: true, align: "center" } },
      { text: "Rationale", options: { fill: { color: theme.primary }, color: "FFFFFF", bold: true, align: "center" } }
    ],
    [
      { text: "1", options: { align: "center" } },
      { text: "validate-tmp-workspace-inputs", options: { align: "left" } },
      { text: "Accept", options: { align: "center", color: "2a9d8f", bold: true } },
      { text: "Upgrade to new best pool", options: { align: "left" } }
    ],
    [
      { text: "2", options: { align: "center" } },
      { text: "multimodal-input-validation-and-setup", options: { align: "left" } },
      { text: "Reject", options: { align: "center", color: "e76f51", bold: true } },
      { text: "Keep current best pool", options: { align: "left" } }
    ],
    [
      { text: "3", options: { align: "center" } },
      { text: "multimodal-creative-task-pipeline", options: { align: "left" } },
      { text: "Reject", options: { align: "center", color: "e76f51", bold: true } },
      { text: "Keep current best pool", options: { align: "left" } }
    ],
    [
      { text: "4", options: { align: "center" } },
      { text: "multimodal-creative-task-pipeline (impr.)", options: { align: "left" } },
      { text: "Reject", options: { align: "center", color: "e76f51", bold: true } },
      { text: "Keep current best pool", options: { align: "left" } }
    ],
    [
      { text: "5", options: { align: "center" } },
      { text: "...pipeline + validate-required-input-files", options: { align: "left" } },
      { text: "Reject", options: { align: "center", color: "e76f51", bold: true } },
      { text: "Keep current best pool", options: { align: "left" } }
    ],
    [
      { text: "6", options: { align: "center" } },
      { text: "multimodal-creative-task-pipeline (cand.)", options: { align: "left" } },
      { text: "Reject", options: { align: "center", color: "e76f51", bold: true } },
      { text: "Not admitted to next cycle", options: { align: "left" } }
    ]
  ];

  slide.addTable(tableData, {
    x: 0.5, y: 0.95, w: 9, h: 3.2,
    colW: [0.5, 3.0, 1.0, 4.5],
    fontFace: "Arial",
    fontSize: 10,
    color: theme.primary,
    border: { pt: 0.5, color: theme.secondary },
    rowH: 0.45
  });

  // Summary stat callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.35, w: 2.5, h: 1.0,
    fill: { color: theme.primary }
  });
  slide.addText("1 of 6", {
    x: 0.5, y: 4.35, w: 2.5, h: 0.65,
    fontSize: 32, fontFace: "Arial",
    color: theme.light, bold: true,
    align: "center", valign: "bottom"
  });
  slide.addText("accepted", {
    x: 0.5, y: 4.95, w: 2.5, h: 0.35,
    fontSize: 12, fontFace: "Arial",
    color: theme.bg, align: "center", valign: "top"
  });

  // Key insight
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 3.2, y: 4.35, w: 6.3, h: 1.0,
    fill: { color: theme.secondary }
  });
  slide.addText("Conservative verification prevents regressions — only skills that demonstrably improve behavior are accepted.", {
    x: 3.4, y: 4.4, w: 5.9, h: 0.9,
    fontSize: 12, fontFace: "Arial",
    color: theme.bg, align: "left", valign: "middle"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("6", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "000814",
    secondary: "001d3d",
    accent: "003566",
    light: "ffc300",
    bg: "ffd60a"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-06-preview.pptx" });
}

