// slide-08.js - Key Takeaways
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'summary',
  index: 8,
  title: 'Key Takeaways: Three Properties That Distinguish SkillClaw'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Title
  slide.addText("Key Takeaways", {
    x: 0.5, y: 0.4, w: 9, h: 0.6,
    fontSize: 36, fontFace: "Arial",
    color: theme.bg, bold: true, align: "left"
  });

  // Three property cards
  const properties = [
    {
      num: "1",
      title: "Collective Evolution",
      desc: "Knowledge from individual interactions contributes to a shared, continuously improving skill ecosystem"
    },
    {
      num: "2",
      title: "Fully Automatic",
      desc: "Skill evolution driven by runtime interaction without manual curation or explicit user intervention"
    },
    {
      num: "3",
      title: "Agentic Evolution Paradigm",
      desc: "Skill updates produced through open-ended reasoning rather than predefined update rules"
    }
  ];

  properties.forEach((prop, i) => {
    const y = 1.2 + i * 1.25;

    // Number circle
    slide.addShape(pres.shapes.OVAL, {
      x: 0.5, y: y, w: 0.55, h: 0.55,
      fill: { color: theme.light }
    });
    slide.addText(prop.num, {
      x: 0.5, y: y, w: 0.55, h: 0.55,
      fontSize: 18, fontFace: "Arial",
      color: theme.primary, bold: true,
      align: "center", valign: "middle"
    });

    // Property title
    slide.addText(prop.title, {
      x: 1.2, y: y, w: 3.5, h: 0.55,
      fontSize: 18, fontFace: "Arial",
      color: theme.light, bold: true,
      align: "left", valign: "middle"
    });

    // Property description
    slide.addText(prop.desc, {
      x: 1.2, y: y + 0.55, w: 8.3, h: 0.6,
      fontSize: 13, fontFace: "Arial",
      color: theme.bg, align: "left", valign: "top"
    });
  });

  // Implications footer
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 4.7, w: 10, h: 0.925,
    fill: { color: theme.secondary }
  });
  slide.addText("Implications: Building continuously improving agent systems where skills evolve from real-world usage, not manual curation", {
    x: 0.5, y: 4.8, w: 9, h: 0.7,
    fontSize: 14, fontFace: "Arial",
    color: theme.bg, align: "center", valign: "middle"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("8", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "000814",
    secondary: "001d3d",
    accent: "003566",
    light: "ffc300",
    bg: "ffd60a"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-08-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

